// What the four sites share: escaped HTML, the page layout, request helpers, per-run state and the other sites'
// addresses.
import { readFileSync } from "node:fs"

const manifest = JSON.parse(readFileSync(new URL("../atira-eval.json", import.meta.url), "utf8"))

/** A site's name as the platform writes it in variable names: erp → ERP, tender-portal → TENDER_PORTAL. */
const variable = (name) => name.toUpperCase().replace(/[^A-Z0-9]/g, "_")

/** The port a site listens on: PORT_<NAME>, which the platform and `atira eval dev` set, else the manifest's. */
export function port(name) {
  const site = manifest.sites.find((candidate) => candidate.name === name)
  return Number(process.env[`PORT_${variable(name)}`] ?? site?.port)
}

/** Where the agent's browser reaches a site: ATIRA_SITE_URL_<NAME> (its public URL), else localhost. */
export function siteUrl(name) {
  return (process.env[`ATIRA_SITE_URL_${variable(name)}`] ?? `http://localhost:${port(name)}`).replace(/\/+$/, "")
}

class Raw {
  constructor(text) {
    this.text = text
  }
}
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`)
const render = (value) =>
  value === null || value === undefined || value === false
    ? ""
    : value instanceof Raw
      ? value.text
      : Array.isArray(value)
        ? value.map(render).join("")
        : escapeHtml(value)

/** Text that goes into the page as it is: only for markup this app wrote itself, never for input. */
export const raw = (text) => new Raw(text)

/** HTML with every value escaped, except other html`` results; arrays are joined. */
/** "1 Woche", "3 Wochen": a count and its noun, singular or plural. */
export const count = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`

export const html = (strings, ...values) =>
  new Raw(strings.reduce((text, part, index) => text + render(values[index - 1]) + part))

/** A whole page: the site's name in the header, its navigation (with "Abmelden"), the title and the content. */
export function page({ site, title, nav = [], body, accent = "#24527a", signedIn = true }) {
  return html`<!doctype html><html lang="de"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} – ${site}</title>
<style>
  header form{margin-left:auto}header button{margin:0}
  body{margin:0;font:15px/1.5 system-ui,sans-serif;color:#1d232a;background:#f4f5f7}
  header{background:${accent};color:#fff;padding:12px 24px;display:flex;gap:24px;align-items:center;flex-wrap:wrap}
  header strong{font-size:17px}header a{color:#fff}main{max-width:960px;margin:24px auto;padding:0 16px}
  main{overflow-x:auto}table{border-collapse:collapse;width:100%;background:#fff}th,td{border:1px solid #c8ced5;padding:6px 10px;text-align:left}
  th{background:#e7ebef}label{display:block;margin:14px 0}input,select{font:inherit;padding:5px 8px;min-width:260px}
  button{font:inherit;padding:6px 14px;margin:8px 12px 8px 0;cursor:pointer}
  .notice{background:#fff7d6;border:1px solid #c9b45d;padding:10px 14px}
  [role=alert]{border:2px solid #a40000;background:#fff;padding:10px 14px;white-space:pre-line}
  dl{display:grid;grid-template-columns:220px 1fr;background:#fff;border:1px solid #c8ced5}dt,dd{margin:0;padding:6px 10px;border-bottom:1px solid #e1e5e9}
  dt{color:#4a5560}pre{white-space:pre-wrap;background:#fff;border:1px solid #c8ced5;padding:14px;font:inherit}
</style></head><body><header><strong>${site}</strong>${nav.map(([href, text]) => html`<a href="${href}">${text}</a>`)}${signedIn ? html`<form method="post" action="/logout"><button type="submit">Abmelden</button></form>` : ""}</header>
<main><h1>${title}</h1>${body}</main></body></html>`.text
}

/** A request's body as text, at most 1 MB. */
export async function readBody(request) {
  const chunks = []
  let size = 0
  for await (const chunk of request) {
    size += chunk.length
    if (size > 1024 * 1024) throw new Error("request body too large")
    chunks.push(chunk)
  }
  return Buffer.concat(chunks).toString("utf8")
}

/** A form post's fields. */
export const readForm = async (request) => Object.fromEntries(new URLSearchParams(await readBody(request)))

export function send(response, status, body, type = "text/html; charset=utf-8") {
  response.writeHead(status, { "content-type": type, "cache-control": "no-store" })
  response.end(body)
}

export const sendJson = (response, status, value) =>
  send(response, status, JSON.stringify(value), "application/json; charset=utf-8")

export function redirect(response, location) {
  response.writeHead(303, { location })
  response.end()
}

/**
 * A run's own state, made on first use: the app serves every run of this eval version at once, so whatever a run can
 * change is kept per login (its run or preview id) and dropped when the login expires.
 */
export function perRun(fresh) {
  const states = new Map()
  return (login) => {
    const now = Date.now()
    for (const [id, entry] of states) if (entry.expiresAt < now) states.delete(id)
    const key = `${login.kind}:${login.id}`
    if (!states.has(key)) states.set(key, { expiresAt: login.expiresAt, state: fresh() })
    return states.get(key).state
  }
}

/** A number as the German sites write money: 1.234,56 */
export const money = (value) => value.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })

/** A date (YYYY-MM-DD or ISO time) as 05.10.2026 */
export const germanDate = (value) => new Date(value).toLocaleDateString("de-DE", { timeZone: "UTC" })

/**
 * A German number as typed into a form: "3,5" or "12"; with `money`, exactly two decimals and optional thousands
 * dots ("1.234,56"). undefined when it isn't one.
 */
export function germanNumber(text, isMoney = false) {
  const pattern = isMoney ? /^(?:0|[1-9]\d*|[1-9]\d{0,2}(?:\.\d{3})+),\d{2}$/ : /^(?:0|[1-9]\d*)(?:,\d{1,2})?$/
  if (!pattern.test(text ?? "")) return undefined
  return Number(text.replaceAll(".", "").replace(",", "."))
}
// The bidder's ERP: the material master with each material's attributes, status, stock, lead times and price scale.
import { bidder, materials } from "../world.js"
import { count, html, money, page, send, siteUrl } from "./html.js"

const nav = () => [
  ["/", "Materialstamm"],
  [`${siteUrl("mail")}/`, "Werkpost"],
]
export const view = (title, body, signedIn) =>
  page({ site: `ERP · ${bidder.name}`, title, nav: nav(), body, accent: "#5b4a2f", signedIn })

export async function erp(request, response) {
  const url = new URL(request.url, "http://erp")
  if (request.method === "GET" && url.pathname === "/") {
    const query = (url.searchParams.get("q") ?? "").toLowerCase()
    const rows = materials.filter((material) => `${material.number} ${material.name}`.toLowerCase().includes(query))
    return send(
      response,
      200,
      view(
        "Materialstamm",
        html`<form method="get" action="/"><label>Katalognummer oder Bezeichnung <input name="q" value="${url.searchParams.get("q") ?? ""}"></label><button type="submit">Suchen</button></form>
        <table><thead><tr><th>Katalognummer</th><th>Bezeichnung</th><th>Status</th></tr></thead><tbody>${rows.map(
          (material) =>
            html`<tr><td><a href="/materials/${material.number}">${material.number}</a></td><td>${material.name}</td><td>${material.status}</td></tr>`,
        )}</tbody></table>`,
      ),
    )
  }
  const number = /^\/materials\/([\w-]+)$/.exec(url.pathname)?.[1]
  const material = materials.find((item) => item.number === number)
  if (request.method === "GET" && material)
    return send(
      response,
      200,
      view(
        `${material.number} · ${material.name}`,
        html`<dl><dt>Status</dt><dd>${material.status}</dd><dt>Bohrung</dt><dd>${material.bore} mm</dd>
        <dt>Hub</dt><dd>${material.stroke} mm</dd><dt>Betriebsdruck</dt><dd>${material.pressure} bar</dd>
        <dt>Befestigung</dt><dd>${material.mounting}</dd><dt>Zertifizierung</dt><dd>${material.certification ?? "keine"}</dd>
        <dt>Bestand</dt><dd>${material.stock} Stk</dd><dt>Lieferzeit ab Lager</dt><dd>${count(material.stockWeeks, "Woche", "Wochen")}</dd>
        <dt>Fertigungszeit</dt><dd>${count(material.productionWeeks, "Woche", "Wochen")}</dd></dl>
        <h2>Preisstaffel (EUR netto je Stück)</h2><table><thead><tr><th>ab Menge</th><th>Preis</th></tr></thead><tbody>${material.prices.map(
          (scale) => html`<tr><td>${scale.from} Stk</td><td>${money(scale.price)}</td></tr>`,
        )}</tbody></table><p><a href="/">Zurück zum Materialstamm</a></p>`,
      ),
    )
  return send(response, 404, view("Material nicht gefunden", html`<p><a href="/">Zum Materialstamm</a></p>`))
}
// The bidder's webmail (Werkpost): the inbox with the customer's request and the discount approvals, and the signing
// TANs the tender portal sends. All four sites run in one process, so the tender portal hands a TAN over with a
// function call; each run has its own inbox, so a run only sees its own TANs.
import { bidder, messages } from "../world.js"
import { germanDate, html, page, perRun, send, siteUrl } from "./html.js"

const inboxOf = perRun(() => [...messages])
const nav = () => [
  ["/", "Posteingang"],
  [`${siteUrl("erp")}/`, "ERP"],
]
export const view = (title, body, signedIn) =>
  page({ site: `Werkpost · ${bidder.mailbox}`, title, nav: nav(), body, accent: "#3d5a3f", signedIn })

/** The tender portal sends a signing TAN: a new message in the run's inbox. */
export function deliverTan(login, tan, reference, count) {
  inboxOf(login).push({
    id: `tan-${count}`,
    date: new Date().toISOString(),
    from: "signatur@vergabeportal.example",
    subject: `Ihre Signatur-TAN für ${reference}`,
    body: `Ihre Signatur-TAN für die Angebotsabgabe zu ${reference} lautet: ${tan}\n\nNur die zuletzt angeforderte TAN ist gültig.`,
  })
}

export async function mail(request, response, login) {
  const url = new URL(request.url, "http://mail")
  const inbox = inboxOf(login)
  if (request.method === "GET" && url.pathname === "/") {
    const query = (url.searchParams.get("q") ?? "").toLowerCase()
    const rows = inbox
      .filter((message) => `${message.from} ${message.subject} ${message.body}`.toLowerCase().includes(query))
      .sort((a, b) => b.date.localeCompare(a.date))
    return send(
      response,
      200,
      view(
        "Posteingang",
        html`<form method="get" action="/"><label>Suche <input name="q" value="${url.searchParams.get("q") ?? ""}"></label><button type="submit">Suchen</button></form>
        <table><thead><tr><th>Datum</th><th>Von</th><th>Betreff</th></tr></thead><tbody>${rows.map(
          (message) =>
            html`<tr><td>${germanDate(message.date)}</td><td>${message.from}</td><td><a href="/messages/${message.id}">${message.subject}</a></td></tr>`,
        )}</tbody></table>`,
      ),
    )
  }
  const id = /^\/messages\/([\w-]+)$/.exec(url.pathname)?.[1]
  const message = inbox.find((item) => item.id === id)
  if (request.method === "GET" && message)
    return send(
      response,
      200,
      view(
        message.subject,
        html`<dl><dt>Von</dt><dd>${message.from}</dd><dt>An</dt><dd>${bidder.mailbox}</dd><dt>Datum</dt><dd>${germanDate(message.date)}</dd></dl>
        <pre>${message.body}</pre><p><a href="/">Zurück zum Posteingang</a></p>`,
      ),
    )
  return send(response, 404, view("Nachricht nicht gefunden", html`<p><a href="/">Zum Posteingang</a></p>`))
}
// The buyer's customer portal (Lieferantenportal): its document register with the technical specification, each
// revision's requirements and the revision history. The Leistungsverzeichnis on the tender portal names a requirement
// per position; this site says what each requirement is. Nothing here changes, so it keeps no per-run state.
import { informationDocuments, specification, tender } from "../world.js"
import { germanDate, html, page, send } from "./html.js"

const nav = [
  ["/", "Startseite"],
  ["/documents", "Dokumente"],
]
export const view = (title, body, signedIn) =>
  page({ site: `Lieferantenportal · ${tender.buyer.name}`, title, nav, body, accent: "#6a2f4f", signedIn })

const current = () => specification.revisions.find((revision) => revision.status === "gültig")

function documents() {
  return view(
    "Dokumente",
    html`<table><thead><tr><th>Dokumentnummer</th><th>Titel</th><th>Typ</th></tr></thead><tbody>
    ${informationDocuments.map(
      (document) =>
        html`<tr><td>${document.number}</td><td><a href="/documents/${document.id}">${document.title}</a></td><td>Allgemein</td></tr>`,
    )}
    <tr><td>${specification.number}</td><td><a href="/documents/specification">${specification.title}</a></td><td>Technische Spezifikation zu ${tender.reference}</td></tr>
    </tbody></table>`,
  )
}

function specificationPage(revision) {
  return view(
    `${specification.number} · ${specification.title}`,
    html`<p>Revision ${revision.revision} vom ${germanDate(revision.date)} · ${revision.status}</p>
    <table><thead><tr><th>Referenz</th><th>Bohrung</th><th>Hub</th><th>Befestigung</th><th>Zertifizierung</th></tr></thead><tbody>${revision.requirements.map(
      (requirement) =>
        html`<tr><td>${requirement.ref}</td><td>${requirement.bore} mm</td><td>${requirement.stroke} mm</td><td>${requirement.mounting}</td><td>${requirement.certification ?? "keine gefordert"}</td></tr>`,
    )}</tbody></table>
    <h2>Revisionshistorie</h2><table><thead><tr><th>Revision</th><th>Datum</th><th>Status</th><th>Änderungsvermerk</th></tr></thead><tbody>${specification.revisions.map(
      (item) =>
        html`<tr><td><a href="/documents/specification?revision=${item.revision}">Revision ${item.revision}</a></td><td>${germanDate(item.date)}</td><td>${item.status}</td><td>${item.note}</td></tr>`,
    )}</tbody></table><p><a href="/documents">Zurück zu den Dokumenten</a></p>`,
  )
}

export async function customerPortal(request, response) {
  const url = new URL(request.url, "http://customer-portal")
  if (request.method !== "GET")
    return send(response, 405, view("Nicht erlaubt", html`<p><a href="/">Zur Startseite</a></p>`))
  if (url.pathname === "/")
    return send(
      response,
      200,
      view(
        "Willkommen im Lieferantenportal",
        html`<p>${tender.buyer.name} stellt Ihnen hier technische Unterlagen und allgemeine Informationen bereit.</p>
        <p><a href="/documents">Zu den Dokumenten</a></p>`,
      ),
    )
  if (url.pathname === "/documents") return send(response, 200, documents())
  if (url.pathname === "/documents/specification") {
    const wanted = url.searchParams.get("revision")
    const revision = wanted ? specification.revisions.find((item) => item.revision === wanted) : current()
    if (revision) return send(response, 200, specificationPage(revision))
  }
  const document = informationDocuments.find((item) => url.pathname === `/documents/${item.id}`)
  if (document)
    return send(
      response,
      200,
      view(
        `${document.number} · ${document.title}`,
        html`<p>${document.content}</p><p><a href="/documents">Zurück zu den Dokumenten</a></p>`,
      ),
    )
  return send(response, 404, view("Seite nicht gefunden", html`<p><a href="/">Zur Startseite</a></p>`))
}

